"""Offline, draggable panorama preview; embeds the rendered image, no network."""
from pathlib import Path
import base64,json
ROOT=Path(__file__).resolve().parents[1]
uri='data:image/png;base64,'+base64.b64encode((ROOT/'previews/15_environment_360.png').read_bytes()).decode('ascii')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>端午古镇 · 360°全景预览</title>
<style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#182422;color:#fff;font:14px "Microsoft YaHei",sans-serif}canvas{display:block;width:100%;height:100%;cursor:grab;touch-action:none}canvas:active{cursor:grabbing}.panel{position:absolute;top:20px;left:20px;padding:15px 18px;background:#10201bc9;border:1px solid #ffffff26;border-radius:9px;backdrop-filter:blur(8px)}h1{font-size:18px;font-weight:500;letter-spacing:2px;margin:0 0 8px}p{margin:0;color:#d5dfd9;font-size:12px}.buttons{display:flex;gap:7px;margin-top:13px}button{color:#f1f4ed;background:#ffffff12;border:1px solid #ffffff38;border-radius:5px;padding:6px 10px;cursor:pointer}button:hover{background:#ffffff2e}.note a{color:#dce8dc;pointer-events:auto}.note{position:absolute;bottom:16px;left:20px;color:#e2e8deaa;font-size:12px;pointer-events:none}#error{position:absolute;inset:45% 0;text-align:center;display:none}</style>
<canvas id="view"></canvas><div class="panel"><h1>端午古镇 · 360°全景</h1><p>拖动环视 · 滚轮缩放 · 双击全屏</p><div class="buttons"><button data-yaw="0">东</button><button data-yaw="-90">南</button><button data-yaw="180">西</button><button data-yaw="90">北</button><button id="reset">复位</button><button id="full">全屏</button></div></div><div class="note">离线全景预览 · 完整三维模型见 dragonboat_models.blend<br>龙头：<a href="https://sketchfab.com/3d-models/chinese-dragon-head-217d9a108f12485088dcaf49b11d9ac0" target="_blank" rel="noopener">CalWhite</a>，<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>，已修改；天空：Greg Zaal / Poly Haven，CC0。</div><div id="error">此浏览器未启用 WebGL，请用 Edge 或 Chrome 打开。</div>
<script>
const canvas=document.getElementById('view'),gl=canvas.getContext('webgl',{alpha:false,antialias:true});
if(!gl){document.getElementById('error').style.display='block'}else{
const vs='attribute vec2 p;varying vec2 uv;void main(){uv=p*.5+.5;gl_Position=vec4(p,0.,1.);}';
const fs='precision highp float;varying vec2 uv;uniform sampler2D photo;uniform float yaw,pitch,ratio,tanHalf;void main(){vec2 q=(uv*2.-1.)*vec2(ratio,1.)*tanHalf;vec3 d=normalize(vec3(q,-1.));float cp=cos(pitch),sp=sin(pitch),cy=cos(yaw),sy=sin(yaw);d=vec3(d.x,cp*d.y-sp*d.z,sp*d.y+cp*d.z);d=vec3(cy*d.x+sy*d.z,d.y,-sy*d.x+cy*d.z);float u=fract(atan(d.x,-d.z)/6.28318530718+.5);float v=asin(clamp(d.y,-1.,1.))/3.14159265359+.5;gl_FragColor=texture2D(photo,vec2(u,v));}';
function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}
const prog=gl.createProgram();gl.attachShader(prog,shader(gl.VERTEX_SHADER,vs));gl.attachShader(prog,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(prog);if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog));gl.useProgram(prog);
const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const attr=gl.getAttribLocation(prog,'p');gl.enableVertexAttribArray(attr);gl.vertexAttribPointer(attr,2,gl.FLOAT,false,0,0);
const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.uniform1i(gl.getUniformLocation(prog,'photo'),0);
const uniforms={};for(const n of ['yaw','pitch','ratio','tanHalf'])uniforms[n]=gl.getUniformLocation(prog,n);
let yaw=0,pitch=0,fov=70,ready=false,drag=false,lastX=0,lastY=0;
function draw(){if(!ready)return;const scale=Math.min(devicePixelRatio||1,2),w=Math.round(innerWidth*scale),h=Math.round(innerHeight*scale);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.uniform1f(uniforms.yaw,yaw);gl.uniform1f(uniforms.pitch,pitch);gl.uniform1f(uniforms.ratio,w/h);gl.uniform1f(uniforms.tanHalf,Math.tan(fov*Math.PI/360));gl.drawArrays(gl.TRIANGLE_STRIP,0,4)}
const image=new Image();image.onload=()=>{gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,image);ready=true;draw()};image.src=__PANORAMA_DATA__;
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-lastX)*.004;pitch=Math.max(-1.45,Math.min(1.45,pitch-(e.clientY-lastY)*.004));lastX=e.clientX;lastY=e.clientY;draw()});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);canvas.addEventListener('wheel',e=>{e.preventDefault();fov=Math.max(35,Math.min(95,fov+e.deltaY*.035));draw()},{passive:false});
for(const b of document.querySelectorAll('[data-yaw]'))b.onclick=()=>{yaw=Number(b.dataset.yaw)*Math.PI/180;pitch=0;draw()};document.getElementById('reset').onclick=()=>{yaw=0;pitch=0;fov=70;draw()};function full(){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen()}document.getElementById('full').onclick=full;canvas.ondblclick=full;window.addEventListener('resize',draw);
}
</script></html>'''
(ROOT/'360全景预览.html').write_text(html.replace('__PANORAMA_DATA__',json.dumps(uri)),encoding='utf-8')
print('OFFLINE_PANORAMA_VIEWER_READY')
